INSERT INTO feature VALUES('qubit-type','calculus','The qubit type with no comonoid','linear-function','partial','uncommon','mainstream languages','`import std.quantum (Qubit);` names the qubit type, which carries no comonoid: only a linear function''s parameter holds a qubit, so a gate is a linear function `(q : Qubit) ⊸ Qubit` that takes it once, and gates nest. A binder that may copy or discard a qubit — at `->`, a bind, a case arm, a declaration, a data field or parameter, or a type argument — is refused `ComonoidAbsent` with its grade, ω or 0, and a copy or a discard in a gate''s body is refused as a linear function refuses it. A `let` of a qubit and a type parameter at `Qubit` are refused, and the kernel does not replay a qubit yet.','core-term core-checker core-incremental surface-lowering surface-pretty surface-diagnostics','corpus/ledger/features/qubit-type.gandr corpus/model/quantum/no-cloning.gandr corpus/ledger/diagnostics/ComonoidAbsent.gandr crates/core-checker-base/src/comonoid/tests.rs','corpus/ledger/features/qubit-type.gandr','#5936 #5943 #5944');
